-- Run after the migration inside BEGIN/ROLLBACK on Staging. Never calls a provider.
create function pg_temp.voice_lease_test(tester uuid,action text,payload jsonb) returns jsonb language plpgsql as $$ begin perform set_config('request.jwt.claims','{"role":"service_role"}',true);return public.native_assistant_voice_lease(tester,action,payload);end $$;
create function pg_temp.voice_connection_test(action text,payload jsonb) returns jsonb language plpgsql as $$ begin perform set_config('request.jwt.claims','{"role":"service_role"}',true);return public.native_assistant_voice_connection(action,payload);end $$;
do $$ declare tester uuid; other_tester uuid; sid uuid; rid uuid:=gen_random_uuid(); rid2 uuid:=gen_random_uuid(); payload jsonb; r jsonb; failures integer:=0; old_count integer; revision integer;
begin
 update feedx_integrations.assistant_voice_policy set enabled=true,per_user_daily_sessions=null where environment='staging';
 select count(*) into old_count from feedx_integrations.native_assistant_realtime_reservations;
 select r.actor into tester from feedx_integrations.native_assistant_realtime_reservations r join public.employees e on e.auth_user_id=r.actor where e.is_active order by r.created_at desc limit 1;
 if tester is null then raise exception 'No authorized fixture actor'; end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 r:=public.native_assistant_service(tester,'session_new','{}');sid:=(r->>'session_id')::uuid;
 payload:=jsonb_build_object('request_id',rid,'session_id',sid,'provider','openai');
 r:=pg_temp.voice_lease_test(tester,'admit',payload);
 if r->>'state'<>'reserved' then raise exception 'Admission blocked by historical count'; end if;
 r:=pg_temp.voice_lease_test(tester,'admit',payload);
 if r->>'replayed'<>'true' then raise exception 'Reconnect not idempotent'; end if;
 if (select count(*) from feedx_integrations.native_assistant_realtime_reservations)<>old_count+1 then raise exception 'Duplicate reservation'; end if;
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',rid2));raise exception 'Concurrent admission accepted';exception when sqlstate '40001' then failures:=failures+1;end;
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('session_id',gen_random_uuid()));raise exception 'Foreign conversation accepted';exception when insufficient_privilege then failures:=failures+1;end;
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||'{"environment":"production"}');raise exception 'Production accepted';exception when insufficient_privilege then failures:=failures+1;end;
 perform pg_temp.voice_lease_test(tester,'ticket',payload||jsonb_build_object('hash',repeat('a',64),'config',jsonb_build_object('voice','cedar','tools','[]'::jsonb,'instructions','fixture')));
 r:=pg_temp.voice_connection_test('claim',jsonb_build_object('hash',repeat('a',64)));
 begin perform pg_temp.voice_connection_test('claim',jsonb_build_object('hash',repeat('a',64)));raise exception 'Offer replay accepted';exception when insufficient_privilege then failures:=failures+1;end;
 select credential_revision into revision from feedx_integrations.native_assistant_providers where provider='openai';
 r:=pg_temp.voice_connection_test('bind',jsonb_build_object('actor',tester,'request_id',rid,'call_id','rtc_fixtureOnly','provider_revision',revision));
 if r->>'state'<>'active' then raise exception 'Provider binding failed'; end if;
 perform pg_temp.voice_lease_test(tester,'heartbeat',payload);
 update feedx_integrations.assistant_voice_leases set expires_at=now()-interval '1 second' where request_id=rid and actor=tester;
 begin perform pg_temp.voice_lease_test(tester,'heartbeat',payload);raise exception 'Expired heartbeat accepted';exception when sqlstate '55000' then failures:=failures+1;end;
 begin perform pg_temp.voice_lease_test(tester,'tool',payload);raise exception 'Expired tool accepted';exception when insufficient_privilege then failures:=failures+1;end;
 insert into feedx_integrations.assistant_voice_cleanup_tickets values(repeat('b',64),now()+interval '30 seconds');
 r:=pg_temp.voice_connection_test('cleanup',jsonb_build_object('hash',repeat('b',64)));
 if jsonb_array_length(r)<>1 or r->0->>'call_id'<>'rtc_fixtureOnly' then raise exception 'Expired call not selected'; end if;
 begin perform pg_temp.voice_connection_test('cleanup',jsonb_build_object('hash',repeat('b',64)));raise exception 'Cleanup ticket replay accepted';exception when insufficient_privilege then failures:=failures+1;end;
 perform pg_temp.voice_connection_test('terminated',jsonb_build_object('actor',tester,'request_id',rid,'status',503));
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',rid2));raise exception 'Failed hangup released slot';exception when sqlstate '40001' then failures:=failures+1;end;
 perform pg_temp.voice_connection_test('terminated',jsonb_build_object('actor',tester,'request_id',rid,'status',200));
 r:=pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',rid2));
 if r->>'state'<>'reserved' then raise exception 'Reconnect after close failed'; end if;
 -- Stale unsubmitted offers are reclaimed; successful provider sessions never become free merely by timing out.
 update feedx_integrations.assistant_voice_leases set expires_at=now()-interval '1 second' where request_id=rid2;
 r:=pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',gen_random_uuid()));
 update feedx_integrations.assistant_voice_leases set state='closed',closed_at=now() where actor=tester;
 update feedx_integrations.assistant_voice_policy set per_user_daily_sessions=0 where environment='staging';
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',gen_random_uuid()));raise exception 'Optional daily limit ignored';exception when sqlstate '54000' then failures:=failures+1;end;
 update feedx_integrations.assistant_voice_policy set per_user_daily_sessions=null,max_concurrent_sessions=1 where environment='staging';
 select id into other_tester from auth.users where id<>tester limit 1;
 if other_tester is null then raise exception 'No second identity for capacity fixture'; end if;
 insert into feedx_integrations.assistant_voice_leases(actor,request_id,session_id,provider,state,expires_at,call_id,provider_revision,connected_at) values(other_tester,gen_random_uuid(),sid,'openai','active',now()+interval '3 minutes','rtc_otherFixture',revision,now());
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',gen_random_uuid()));raise exception 'Environment capacity ignored';exception when sqlstate '54000' then failures:=failures+1;end;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.native_assistant_voice_usage(tester,'save',jsonb_build_object('revision',(select p.revision from feedx_integrations.assistant_voice_policy p where environment='staging'),'enabled',false,'maximum_seconds',180,'concurrency',1,'daily_sessions',null));
 if not exists(select 1 from feedx_integrations.assistant_voice_leases where actor=other_tester and state='closing' and reason='admin_disabled') then raise exception 'Emergency disable did not revoke active calls';end if;
 begin perform pg_temp.voice_lease_test(tester,'admit',payload||jsonb_build_object('request_id',gen_random_uuid()));raise exception 'Disabled environment accepted';exception when insufficient_privilege then failures:=failures+1;end;
 if exists(select 1 from feedx_integrations.assistant_voice_policy where environment='production' and enabled) then raise exception 'Production activated';end if;
 if has_function_privilege('authenticated','public.native_assistant_voice_connection(text,jsonb)','execute') then raise exception 'Worker exposed';end if;
 if failures<>11 then raise exception 'Expected eleven denials; got %',failures;end if;
 raise notice 'Voice admission, idempotency, concurrency, ownership, production denial, expiry, cleanup replay, termination retry and reconnect passed';
end $$;
